// --- Helpers -----------------------------------------------------------------

template <typename V>
bool parse_hex_checked(const char* text, V& out) {
    const auto parsed = V::parse(text, 16);
    if (!parsed.ok()) {
        CRPC_CHECK_EQ(std::string(text) + " (hex)", std::string("<parse failed>"));
        return false;
    }
    out = parsed.value();
    return true;
}

template <typename V>
void check_hex(const char* expected_hex, const V& actual) {
    CRPC_CHECK_EQ(std::string(expected_hex), actual.to_string(16));
}

template <typename V>
void run_add_sub_vectors(const arith_vector* rows, std::size_t count) {
    for (std::size_t i = 0; i < count; ++i) {
        const arith_vector& row = rows[i];
        V a;
        V b;
        if (!parse_hex_checked(row.a, a) || !parse_hex_checked(row.b, b)) {
            continue;
        }
        const V sum = a + b;
        check_hex(row.sum, sum);
        check_hex(row.sum, b + a);
        check_hex(row.difference, a - b);

        // (a + b) - b == a only when the addition did not wrap; on wrap the
        // result is the wrapped value, which is exactly what built-in unsigned
        // arithmetic does. `sum >= a` is the wrap test.
        if (sum >= a) {
            check_hex(row.a, sum - b);
        }

        V accumulated = a;
        accumulated += b;
        check_hex(row.sum, accumulated);
        accumulated -= b;
        if (sum >= a) {
            check_hex(row.a, accumulated);
        }

        // Post forms return the previous value; pre forms return the new one.
        // Both move the stored value by exactly one, wrapping like the
        // built-in type.
        V counter = a;
        const V post_increment = counter++;
        check_hex(row.a, post_increment);
        CRPC_CHECK(counter == a + V(1));
        const V pre_decrement = --counter;
        check_hex(row.a, pre_decrement);
        CRPC_CHECK(counter == a);
        const V pre_increment = ++counter;
        CRPC_CHECK(pre_increment == a + V(1));
        const V post_decrement = counter--;
        CRPC_CHECK(post_decrement == a + V(1));
        CRPC_CHECK(counter == a);
        const V wrapped = V::max() + V(1);
        CRPC_CHECK(wrapped.is_zero());
        V wrap_step = V::max();
        ++wrap_step;
        CRPC_CHECK(wrap_step.is_zero());
        --wrap_step;
        CRPC_CHECK(wrap_step == V::max());

        // Ordering oracle: the two canonical hex strings from Python, padded
        // to the fixed byte width. Lexicographic order on equal-length hex is
        // numeric order, and it does not reuse this implementation's
        // comparison or its to_string().
        std::string a_hex(row.a);
        std::string b_hex(row.b);
        a_hex.insert(0, V::byte_count * 2 - a_hex.size(), '0');
        b_hex.insert(0, V::byte_count * 2 - b_hex.size(), '0');
        CRPC_CHECK((a < b) == (a_hex < b_hex));
        CRPC_CHECK((a > b) == (a_hex > b_hex));
        CRPC_CHECK((a == b) == (a_hex == b_hex));
        CRPC_CHECK((a != b) == (a_hex != b_hex));
        CRPC_CHECK((a <= b) == (a_hex <= b_hex));
        CRPC_CHECK((a >= b) == (a_hex >= b_hex));
    }
}

template <typename V>
void run_mul_vectors(const arith_vector* rows, std::size_t count) {
    for (std::size_t i = 0; i < count; ++i) {
        const arith_vector& row = rows[i];
        V a;
        V b;
        if (!parse_hex_checked(row.a, a) || !parse_hex_checked(row.b, b)) {
            continue;
        }
        check_hex(row.product, a * b);
        check_hex(row.product, b * a);
        V accumulated = a;
        accumulated *= b;
        check_hex(row.product, accumulated);
    }
}

template <typename V>
void run_div_vectors(const arith_vector* rows, std::size_t count) {
    for (std::size_t i = 0; i < count; ++i) {
        const arith_vector& row = rows[i];
        V a;
        V b;
        if (!parse_hex_checked(row.a, a) || !parse_hex_checked(row.b, b)) {
            continue;
        }
        check_hex(row.quotient, a / b);
        check_hex(row.remainder, a % b);

        const auto checked = V::divmod(a, b);
        CRPC_REQUIRE(checked.ok());
        check_hex(row.quotient, checked.value().quotient);
        check_hex(row.remainder, checked.value().remainder);

        // The defining identity q * b + r == a, evaluated in the wrap-around
        // arithmetic of this width.
        const V recomposed = checked.value().quotient * b + checked.value().remainder;
        check_hex(row.a, recomposed);
        CRPC_CHECK(checked.value().remainder < b || b.is_zero());
    }
}

template <typename V>
void run_knuth_vectors(const divmod_vector* rows, std::size_t count) {
    for (std::size_t i = 0; i < count; ++i) {
        const divmod_vector& row = rows[i];
        V a;
        V b;
        if (!parse_hex_checked(row.a, a) || !parse_hex_checked(row.b, b)) {
            continue;
        }
        check_hex(row.quotient, a / b);
        check_hex(row.remainder, a % b);
        const auto checked = V::divmod(a, b);
        CRPC_REQUIRE(checked.ok());
        check_hex(row.quotient, checked.value().quotient);
        check_hex(row.remainder, checked.value().remainder);
        check_hex(row.a, checked.value().quotient * b + checked.value().remainder);
    }
}

template <typename V>
void run_shift_vectors(const shift_vector* rows, std::size_t count) {
    for (std::size_t i = 0; i < count; ++i) {
        const shift_vector& row = rows[i];
        V value;
        if (!parse_hex_checked(row.value, value)) {
            continue;
        }
        const V shifted_left = value << row.count;
        check_hex(row.left, shifted_left);
        const V shifted_right = value >> row.count;
        check_hex(row.right, shifted_right);

        V in_place = value;
        in_place <<= row.count;
        check_hex(row.left, in_place);
        in_place = value;
        in_place >>= row.count;
        check_hex(row.right, in_place);

        // Shift by >= width yields zero, shift by 0 is the identity.
        if (row.count >= V::bit_width) {
            CRPC_CHECK((value << row.count).is_zero());
            CRPC_CHECK((value >> row.count).is_zero());
        }
        if (row.count == 0) {
            check_hex(row.value, value << 0);
            check_hex(row.value, value >> 0);
        }
    }
}

template <typename V>
void run_bitwise_vectors(const bitwise_vector* rows, std::size_t count) {
    for (std::size_t i = 0; i < count; ++i) {
        const bitwise_vector& row = rows[i];
        V a;
        V b;
        if (!parse_hex_checked(row.a, a) || !parse_hex_checked(row.b, b)) {
            continue;
        }
        check_hex(row.and_value, a & b);
        check_hex(row.or_value, a | b);
        check_hex(row.xor_value, a ^ b);
        check_hex(row.not_value, ~a);

        V accumulated = a;
        accumulated &= b;
        check_hex(row.and_value, accumulated);
        accumulated = a;
        accumulated |= b;
        check_hex(row.or_value, accumulated);
        accumulated = a;
        accumulated ^= b;
        check_hex(row.xor_value, accumulated);

        // De Morgan, as a structural sanity check independent of the vectors.
        check_hex(row.not_value, ~a);
        CRPC_CHECK((~(a & b)) == (~a | ~b));
        CRPC_CHECK((~(a | b)) == (~a & ~b));
    }
}

template <typename V>
void run_text_vectors(const text_vector* rows, std::size_t count) {
    for (std::size_t i = 0; i < count; ++i) {
        const text_vector& row = rows[i];
        V value;
        if (!parse_hex_checked(row.hex, value)) {
            continue;
        }
        CRPC_CHECK_EQ(std::string(row.decimal), value.to_string(10));
        CRPC_CHECK_EQ(std::string(row.hex), value.to_string(16));
        CRPC_CHECK_EQ(std::string(row.binary), value.to_string(2));

        const auto back_decimal = V::parse(value.to_string(10), 10);
        CRPC_REQUIRE(back_decimal.ok());
        check_hex(row.hex, back_decimal.value());
        const auto back_binary = V::parse(value.to_string(2), 2);
        CRPC_REQUIRE(back_binary.ok());
        check_hex(row.hex, back_binary.value());

        // Leading zeros must not change the value.
        const auto padded = V::parse(std::string(5, '0') + value.to_string(10), 10);
        CRPC_REQUIRE(padded.ok());
        check_hex(row.hex, padded.value());
    }
}

template <typename V>
void run_parse_vectors(const parse_vector* rows, std::size_t count) {
    for (std::size_t i = 0; i < count; ++i) {
        const parse_vector& row = rows[i];
        const auto parsed = V::parse(row.text, static_cast<int>(row.base));
        if (!parsed.ok()) {
            CRPC_CHECK_EQ(std::string(row.text) + " base " +
                              std::to_string(row.base),
                          std::string("<parse failed>"));
            continue;
        }
        check_hex(row.hex, parsed.value());
    }
}

template <typename V>
void run_parse_bad_vectors(const parse_bad_vector* rows, std::size_t count) {
    for (std::size_t i = 0; i < count; ++i) {
        const parse_bad_vector& row = rows[i];
        const auto parsed = V::parse(row.text, static_cast<int>(row.base));
        if (parsed.ok()) {
            CRPC_CHECK_EQ(std::string(row.text) + " base " +
                              std::to_string(row.base),
                          std::string("<must be rejected>"));
            continue;
        }
        CRPC_CHECK(parsed.code() == crpc::rpc_code::invalid_argument);
    }
}

template <typename V>
void run_byte_vectors(const text_vector* rows, std::size_t count) {
    for (std::size_t i = 0; i < count; ++i) {
        const text_vector& row = rows[i];
        V value;
        if (!parse_hex_checked(row.hex, value)) {
            continue;
        }

        // The expected big-endian image is the vector's hex, left-padded to
        // the full byte width. Padding is the only transformation applied.
        std::string expected(V::byte_count * 2, '0');
        const std::string hex(row.hex);
        expected.replace(expected.size() - hex.size(), hex.size(), hex);

        const auto bytes = value.to_be_bytes();
        std::string rendered;
        rendered.reserve(bytes.size() * 2);
        static const char digits[] = "0123456789abcdef";
        for (const std::byte b : bytes) {
            const unsigned v = std::to_integer<unsigned>(b);
            rendered.push_back(digits[v >> 4]);
            rendered.push_back(digits[v & 0xF]);
        }
        CRPC_CHECK_EQ(expected, rendered);

        const auto round = V::from_be_bytes(
            crpc::span<const std::byte>(bytes.data(), bytes.size()));
        CRPC_REQUIRE(round.ok());
        check_hex(row.hex, round.value());

        // A shorter span is zero-extended on the most significant side, so
        // passing the trailing byte_count-1 bytes (dropping the leading one)
        // must recover exactly the low bits of the value.
        const auto shorter = V::from_be_bytes(
            crpc::span<const std::byte>(bytes.data() + 1, bytes.size() - 1));
        CRPC_REQUIRE(shorter.ok());
        const V low_mask = (V(static_cast<std::uint64_t>(1))
                            << static_cast<unsigned>((V::byte_count - 1) * 8)) -
                           V(1);
        check_hex(row.hex, shorter.value() + (value & ~low_mask));
        CRPC_CHECK(shorter.value() == (value & low_mask));
    }
}

template <typename V>
void run_empty_span() {
    const auto empty = V::from_be_bytes(crpc::span<const std::byte>());
    CRPC_REQUIRE(empty.ok());
    CRPC_CHECK(empty.value().is_zero());

    // One byte more than the width must be rejected rather than truncated.
    std::array<std::byte, V::byte_count + 1> oversized{};
    const auto too_wide = V::from_be_bytes(
        crpc::span<const std::byte>(oversized.data(), oversized.size()));
    CRPC_CHECK_FALSE(too_wide.ok());
    CRPC_CHECK(too_wide.code() == crpc::rpc_code::invalid_argument);
}

template <typename V>
void run_width_properties() {
    const V maximum = V::max();
    CRPC_CHECK(maximum.is_zero() == false);
    CRPC_CHECK(maximum.to_string(16) == std::string(V::byte_count * 2, 'f'));
    CRPC_CHECK(V::zero().is_zero());
    CRPC_CHECK(V::zero().to_string(16) == "0");
    CRPC_CHECK(static_cast<bool>(maximum));
    CRPC_CHECK_FALSE(static_cast<bool>(V::zero()));
    CRPC_CHECK(maximum.low64() == ~static_cast<std::uint64_t>(0));
    CRPC_CHECK(V(0x0123456789ABCDEFull).low64() == 0x0123456789ABCDEFull);
    CRPC_CHECK(maximum.limb(0) == ~static_cast<std::uint64_t>(0));
    CRPC_CHECK(maximum.limb(V::limb_count - 1) == ~static_cast<std::uint64_t>(0));
    CRPC_CHECK(maximum.limb(V::limb_count) == 0);
    CRPC_CHECK(maximum.significant_limbs() == V::limb_count);
    CRPC_CHECK(V::zero().significant_limbs() == 0);
    CRPC_CHECK(V(1).significant_limbs() == 1);

    // Every bit position must be observable, including the top one.
    for (std::size_t index = 0; index < V::bit_width; ++index) {
        const V single = V(static_cast<std::uint64_t>(1)) << static_cast<unsigned>(index);
        CRPC_CHECK(single.bit(index));
        CRPC_CHECK(single.significant_limbs() == index / 64 + 1);
        if (index != 0) {
            CRPC_CHECK_FALSE(single.bit(index - 1));
        }
    }
    CRPC_CHECK_FALSE(maximum.bit(V::bit_width));
    CRPC_CHECK_FALSE(V::zero().bit(0));

    // Wrap-around boundaries: max + 1 == 0, 0 - 1 == max.
    CRPC_CHECK((maximum + V(1)).is_zero());
    CRPC_CHECK((V::zero() - V(1)) == maximum);
    CRPC_CHECK((maximum * V(2)) == (maximum - V(1)));
    CRPC_CHECK((maximum * maximum) == V(1));
    CRPC_CHECK((V(1) << static_cast<unsigned>(V::bit_width)) .is_zero());
    CRPC_CHECK((maximum >> static_cast<unsigned>(V::bit_width - 1)) == V(1));
    CRPC_CHECK((maximum >> static_cast<unsigned>(V::bit_width)) .is_zero());

    // Increment/decrement wrap.
    V counter = maximum;
    ++counter;
    CRPC_CHECK(counter.is_zero());
    --counter;
    CRPC_CHECK(counter == maximum);

    // Construction from signed values follows built-in two's-complement
    // conversion: -1 is the all-ones value, -2 is max - 1.
    CRPC_CHECK(V(-1) == maximum);
    CRPC_CHECK(V(-2) == maximum - V(1));
    CRPC_CHECK(V(static_cast<std::int8_t>(-1)) == maximum);
    CRPC_CHECK(V(true) == V(1));
    CRPC_CHECK(V(static_cast<std::uint8_t>(255)) == V(255));
    CRPC_CHECK(V(static_cast<std::uint32_t>(0xFFFFFFFFu)) == V(0xFFFFFFFFull));
}

template <typename V>
void run_divide_by_zero() {
    const auto zero_divisor = V::divmod(V(12345), V::zero());
    CRPC_CHECK_FALSE(zero_divisor.ok());
    CRPC_CHECK(zero_divisor.code() == crpc::rpc_code::invalid_argument);

    const auto zero_dividend = V::divmod(V::zero(), V(7));
    CRPC_REQUIRE(zero_dividend.ok());
    CRPC_CHECK(zero_dividend.value().quotient.is_zero());
    CRPC_CHECK(zero_dividend.value().remainder.is_zero());

    // Dividend below the divisor: quotient 0, remainder is the dividend.
    const auto below = V::divmod(V(41), V(42));
    CRPC_REQUIRE(below.ok());
    CRPC_CHECK(below.value().quotient.is_zero());
    CRPC_CHECK(below.value().remainder == V(41));

    // Equal operands: quotient 1, remainder 0.
    const auto equal = V::divmod(V::max(), V::max());
    CRPC_REQUIRE(equal.ok());
    CRPC_CHECK(equal.value().quotient == V(1));
    CRPC_CHECK(equal.value().remainder.is_zero());
}

